    'Facebook asks you to sign in and to choose the pages; each chosen page joins your accounts, with its messages, comments, posts and numbers.' => 'فيسبوك هيطلب تسجيل الدخول واختيار الصفحات؛ كل صفحة تختارها بتنضم لحساباتك برسائلها وكومنتاتها ومنشوراتها وأرقامها.',
    'Advanced: add a page by hand (page token and app secret)' => 'متقدم: إضافة صفحة يدوياً (توكن الصفحة وسر التطبيق)',
    'After adding, the page\'s card shows its own webhook address and verify token to paste in the app.' => 'بعد الإضافة، كارت الصفحة بيعرض عنوان الـWebhook وكود التحقق الخاصين بيها علشان تلصقهم في التطبيق.',
    'Sign in with Facebook and choose your pages' => 'سجّل دخول بفيسبوك واختار صفحاتك',
    'One button: Facebook asks you to sign in and to pick the pages; their messages, comments, posts and numbers come in by themselves. Nothing to copy or type.' => 'زرار واحد: فيسبوك هيطلب تسجيل الدخول واختيار الصفحات، ورسايلها وكومنتاتها ومنشوراتها وأرقامها بتتسحب لوحدها. مفيش حاجة تنسخها أو تكتبها.',
    'Continue with Facebook' => 'المتابعة باستخدام فيسبوك',
    'Set up the Facebook app once below; after that everyone connects with the button.' => 'اضبط تطبيق فيسبوك مرة واحدة تحت؛ بعدها أي حد يربط بالزرار.',
    'The Facebook sign-in is not set up yet. Ask the administrator, or set up an app of your own below.' => 'تسجيل الدخول بفيسبوك لسه مش مضبوط. اطلب من المسؤول، أو اضبط تطبيقك الخاص تحت.',
    'Facebook app settings (once, by the administrator)' => 'إعدادات تطبيق فيسبوك (مرة واحدة، من المسؤول)',
    'Use an app of your own (optional)' => 'استخدام تطبيق خاص بك (اختياري)',
    'Connect a Facebook page to this number: it answers with this number\'s knowledge' => 'اربط صفحة فيسبوك بالرقم ده: بترد بمعرفة الرقم ده',
    'Configuration ID' => 'معرّف الإعداد (Configuration ID)',
    '(Facebook Login for Business — Business apps)' => '(Facebook Login for Business — لتطبيقات Business)',
    'Owner name on the privacy policy and terms pages (empty = product name)' => 'اسم المالك في صفحتي الخصوصية والشروط (فاضي = اسم المنتج)',
    'Contact e-mail on those pages' => 'إيميل التواصل في الصفحتين دول',
    'Privacy policy page (index.php?privacy) — empty = the built-in text; "# " starts a heading' => 'صفحة سياسة الخصوصية (index.php?privacy) — فاضي = النص الجاهز؛ "# " في أول السطر = عنوان',
    'Terms of service page (index.php?terms) — empty = the built-in text' => 'صفحة شروط الاستخدام (index.php?terms) — فاضي = النص الجاهز',
    'Empty = the built-in text' => 'فاضي = النص الجاهز',
    '# Terms of service' => '# شروط الاستخدام',
    '{product} is a messaging dashboard run by {owner} ({site}). By using it you agree to these terms.' => '{product} لوحة لإدارة الرسائل يشغّلها {owner} ({site}). باستخدامك لها توافق على هذه الشروط.',
    '# The service' => '# الخدمة',
    'The dashboard connects the business accounts you choose (WhatsApp numbers, Facebook pages) and lets your team read and answer their messages, comments and posts, with optional automatic replies.' => 'تربط اللوحة حسابات النشاط التي تختارها (أرقام واتساب وصفحات فيسبوك) ويقرأ فريقك رسائلها وتعليقاتها ومنشوراتها ويرد عليها، مع ردود تلقائية اختيارية.',
    '# Your responsibilities' => '# مسؤولياتك',
    'You connect only accounts you are allowed to manage, you follow the rules of WhatsApp and Meta, and you do not send spam or unlawful content.' => 'تربط فقط الحسابات المسموح لك بإدارتها، وتلتزم بقواعد واتساب وميتا، ولا ترسل رسائل مزعجة أو محتوى مخالفاً للقانون.',
    '# Availability' => '# التوفر',
    'The service is provided as it is; we work to keep it running but cannot promise it will never stop. We may change or end features with notice.' => 'تُقدَّم الخدمة كما هي؛ نعمل على استمرارها دون ضمان عدم توقفها، وقد نغيّر الميزات أو نوقفها مع إشعار.',
    '# Ending' => '# الإنهاء',
    'You can disconnect your accounts and ask us to delete your data at any time. We may suspend accounts that break these terms.' => 'يمكنك فصل حساباتك وطلب حذف بياناتك في أي وقت، وقد نوقف الحسابات المخالفة لهذه الشروط.',
    '# Contact' => '# التواصل',
    '# Privacy policy' => '# سياسة الخصوصية',
    '{product} is run by {owner} ({site}). This page explains what data the service handles and why.' => '{product} يشغّلها {owner} ({site}). توضح هذه الصفحة البيانات التي تتعامل معها الخدمة ولماذا.',
    '# What we handle' => '# ما نتعامل معه',
    'When a business connects a WhatsApp number or a Facebook page, the service receives the messages, comments, names, profile pictures and files sent to that account, and the replies the business sends. It also keeps the access tokens needed to work with the account, stored encrypted.' => 'عند ربط النشاط لرقم واتساب أو صفحة فيسبوك، تستقبل الخدمة الرسائل والتعليقات والأسماء وصور الملف الشخصي والملفات المرسلة لهذا الحساب، وردود النشاط عليها، وتحتفظ برموز الوصول اللازمة مشفّرة.',
    '# Why' => '# لماذا',
    'Only to show these conversations to the business and its team, to send their replies, and — when the business turns it on — to suggest or send automatic replies. We do not sell data and do not use it for advertising.' => 'فقط لعرض هذه المحادثات للنشاط وفريقه، وإرسال ردودهم، واقتراح أو إرسال ردود تلقائية عندما يفعّلها النشاط. لا نبيع البيانات ولا نستخدمها للإعلانات.',
    '# Sharing' => '# المشاركة',
    'Data is shared only with the services needed to run the dashboard (the messaging platforms themselves and, for automatic replies, an AI provider chosen by the business), and when the law requires it.' => 'تُشارك البيانات فقط مع الخدمات اللازمة لتشغيل اللوحة (منصات المراسلة نفسها، ومزوّد الذكاء الاصطناعي الذي يختاره النشاط للردود التلقائية)، وعندما يطلب القانون ذلك.',
    '# Keeping and deleting' => '# الحفظ والحذف',
    'Data is kept while the account stays connected. A business can disconnect an account at any time; a person can ask for their data to be deleted by writing to {email}, and Facebook users can also use Facebook\'s data deletion request. We confirm and complete deletion within 30 days.' => 'تُحفظ البيانات ما دام الحساب مربوطاً. يمكن للنشاط فصل الحساب في أي وقت، ويمكن لأي شخص طلب حذف بياناته بالكتابة إلى {email}، ولمستخدمي فيسبوك أيضاً استخدام طلب حذف البيانات من فيسبوك. نؤكد الحذف وننفذه خلال 30 يوماً.',
    '# Security' => '# الأمان',
    'Access needs a sign-in with a one-time code; tokens and private files are encrypted; only the business\'s team sees its data.' => 'الدخول برمز لمرة واحدة، ورموز الوصول والملفات الخاصة مشفّرة، ولا يرى بيانات النشاط إلا فريقه.',
    '••••••••  saved — leave empty to keep it' => '••••••••  محفوظ — سيبه فاضي علشان يفضل زي ما هو',
    'Facebook did not give these permissions, so comments, posts and numbers stay off (messages work):' => 'فيسبوك ما اداش الصلاحيات دي، فالكومنتات والمنشورات والأرقام مقفولة (الرسايل شغالة):',
    'Add them to the app\'s login configuration, then press Reconnect.' => 'ضيفها لإعداد تسجيل الدخول في التطبيق، وبعدين اضغط إعادة الربط.',
