    'Add page' => 'إضافة الصفحة',
    "Messages of the page's inbox arrive here and every inbox tool works on them: replies, bot, library, tags, notes and team. After adding, copy the webhook address and code shown on the page card into the app's Messenger settings." => 'رسائل صندوق الصفحة بتوصل هنا وكل أدوات الصندوق شغالة عليها: الرد والبوت والمكتبة والوسوم والملاحظات والفريق. بعد الإضافة انسخ عنوان الـ Webhook والكود الظاهرين في كارت الصفحة داخل إعدادات ماسنجر في التطبيق.',
    'Webhook address' => 'عنوان الـ Webhook',
