    'e.g. Sales number' => 'مثلاً: رقم المبيعات',
    'After adding, the QR appears on the Link page. Scan it from the new phone: WhatsApp → Linked devices → Link a device.' => 'بعد الإضافة، الكود بيظهر في صفحة الربط. امسحه من الموبايل الجديد: واتساب ← الأجهزة المرتبطة ← ربط جهاز.',
    'Add account' => 'إضافة الحساب',
    'port' => 'بورت',
    'chats' => 'محادثات',
    'Remove this account? Its gateway stops; its archive stays on the server.' => 'حذف الحساب؟ الجيتواي بتاعه هيقف، والأرشيف يفضل محفوظ على السيرفر.',
    'Give the account a name (up to 60 characters).' => 'اكتب اسم للحساب (60 حرف كحد أقصى).',
    'No free port for another account.' => 'مافيش بورت متاح لحساب جديد.',
    'Account added. Its gateway starts within a minute — then scan the QR below.' => 'تمت إضافة الحساب. الجيتواي بيشتغل خلال دقيقة — بعدها امسح الكود.',
    'Account not found.' => 'الحساب غير موجود.',
    'The main account cannot be deleted.' => 'الحساب الأساسي لا يمكن حذفه.',
    'Account removed. Its gateway stops within a minute; its archive is kept on the server.' => 'تم حذف الحساب. الجيتواي بيقف خلال دقيقة، والأرشيف محفوظ.',
    'Account updated.' => 'تم تحديث الحساب.',
    '➕ Add another WhatsApp account' => '➕ إضافة حساب واتساب آخر',
