    'Type a reply…' => 'اكتب ردك…',
    'Send' => 'إرسال',
    '🛡️ Replies only in existing chats · typing indicator · max 1 message / 3 s and 20 / minute.' => '🛡️ الرد في المحادثات الموجودة فقط · يظهر «يكتب…» · رسالة كل 3 ثواني و20 في الدقيقة كحد أقصى.',
    'Can reply from the Inbox' => 'يقدر يرد من الصفحة',
    'Sending…' => 'جاري الإرسال…',
    'Not sent:' => 'لم يتم الإرسال:',
    'You' => 'أنت',
    'Drag to move the menu' => 'اسحب لتحريك القائمة',
    'Lock / unlock the menu' => 'قفل / فتح القائمة',
    'Drop here' => 'أفلت هنا',
    'Starting… the QR will appear within a minute.' => 'جاري التشغيل… الكود هيظهر خلال دقيقة.',
    'Gateway &amp; Guard' => 'الجيتواي والحارس',
    'Gateway & Guard' => 'الجيتواي والحارس',
    'Live status of every number\'s gateway, restart controls, and the Guard that keeps them running.' => 'حالة جيتواي كل رقم، وأزرار إعادة التشغيل، والحارس اللي بيحافظ عليهم شغالين.',
    'Auto-restart' => 'إعادة تشغيل تلقائي',
    'Every minute' => 'كل دقيقة',
    'Main number — last check' => 'الرقم الأساسي — آخر فحص',
    'Other numbers — last check' => 'باقي الأرقام — آخر فحص',
    'Auto-reconnect' => 'إعادة اتصال تلقائي',
    'On (backoff up to 60 s)' => 'شغال (بفواصل حتى 60 ثانية)',
    'If a gateway stops, the Guard starts it again within a minute. If WhatsApp disconnects, the gateway reconnects by itself; you get a WhatsApp alert if it stays down.' => 'لو جيتواي وقف، الحارس بيشغله تاني خلال دقيقة. ولو واتساب فصل، الجيتواي بيرجع يتصل لوحده، ولو فضل واقف بيوصلك تنبيه على واتساب.',
    '🟢 Active' => '🟢 شغال',
