    'ago' => 'مضت',
    'Messages since start' => 'رسائل منذ التشغيل',
    'Reconnect attempts' => 'محاولات إعادة الاتصال',
    'Guard restarts (24 h)' => 'إعادات تشغيل الحارس (24 ساعة)',
    'Last error' => 'آخر خطأ',
    'Reconnect' => 'إعادة الاتصال',
    'Restart gateway' => 'إعادة تشغيل الجيتواي',
    'No numbers you can manage.' => 'لا توجد أرقام تقدر تديرها.',
    'Restart this gateway? It comes back within a minute; the link to WhatsApp is kept.' => 'إعادة تشغيل الجيتواي؟ هيرجع خلال دقيقة، والربط بواتساب بيفضل زي ما هو.',
    'Can link their own number (one) from the panel' => 'يقدر يربط رقمه الخاص (رقم واحد) من اللوحة',
    'You can link one number of your own. Ask an admin for more.' => 'تقدر تربط رقم واحد خاص بيك. للمزيد كلم الأدمن.',
