    'to a person' => 'اتحوّل لشخص',
    'Regular bot' => 'البوت العادي',
    'Rules for every role (no invention, no repeating)' => 'قواعد لكل الأدوار (من غير تأليف ولا تكرار)',
    'One bot, several hats: a message with a role\'s words is answered in that role, and the chat keeps it for a few hours. Anything else is answered by the regular bot.' => 'بوت واحد بأكتر من دور: الرسالة اللي فيها كلمات دور معيّن بيرد عليها بالدور ده، والمحادثة بتفضل عليه كام ساعة. أي حاجة تانية بيرد عليها البوت العادي.',
    'Keep the role in a chat (hours)' => 'المحادثة تفضل على الدور (ساعات)',
    'Strong models, in order (providers)' => 'الموديلات القوية بالترتيب (المزوّدين)',
    'Strong model now' => 'الموديل القوي دلوقتي',
    'none — turn on OpenCode Go or Gemini in AI providers' => 'مفيش — فعّل OpenCode Go أو Gemini في مزوّدين الذكاء الاصطناعي',
    'Use a strong model' => 'استخدم موديل قوي',
    'Words that call this role (comma)' => 'الكلمات اللي بتشغّل الدور (بفاصلة)',
    'Instructions' => 'التعليمات',
    'Note in the first reply' => 'جملة في أول رد',
    'Danger safeguard' => 'الحماية وقت الخطر',
    'Words that show danger (self-harm, suicide, violence): the bot stops in that chat, sends the fixed support message (Message templates → crisis_reply) and alerts the team at once.' => 'كلمات فيها خطر (إيذاء النفس، انتحار، عنف): البوت يقف في المحادثة دي، يبعت رسالة الدعم الثابتة (قوالب الرسائل ← crisis_reply) وينبّه الفريق فورًا.',
    'Danger words (comma)' => 'كلمات الخطر (بفاصلة)',
