    'When a customer compares, names a competitor or hesitates, the bot answers politely with what sets you apart. It never speaks badly of anyone and never invents a discount.' => 'لما العميل يقارن أو يذكر منافس أو يتردد، البوت بيرد بأدب بمميزاتك. عمره ما يتكلم وحش عن حد، ولا يألّف خصم.',
    'What sets us apart' => 'إيه اللي بيميّزنا',
    'e.g. original products with a guarantee, delivery in a day, return within 14 days' => 'مثلاً: منتجات أصلية بضمان، توصيل في يوم، استرجاع خلال 14 يوم',
    'What the bot may offer a hesitant customer (empty = nothing)' => 'العرض اللي البوت يقدر يقدّمه للعميل المتردد (فاضي = ولا حاجة)',
    'e.g. free delivery on the first order' => 'مثلاً: توصيل مجاني لأول طلب',
    'Competitor name' => 'اسم المنافس',
    'Competitor' => 'المنافس',
    'Their prices' => 'أسعارهم',
    'Where we do better' => 'إحنا أحسن في إيه',
    'Add competitor' => 'ضيف منافس',
    'AI market analysis' => 'تحليل السوق بالذكاء الاصطناعي',
    'Reads your products, what sets you apart, your competitors and what customers wrote in the last 30 days: price objections, competitors they named and why they hesitated. It also runs by itself once a week.' => 'بيقرا منتجاتك، واللي بيميّزك، ومنافسينك، واللي كتبه العملاء آخر 30 يوم: اعتراضات السعر، والمنافسين اللي اتذكروا، وأسباب التردد. وبيشتغل لوحده مرة كل أسبوع.',
    'Optional: what to look at, e.g. why customers say we are expensive' => 'اختياري: تحب يركّز على إيه؟ مثلاً: ليه العملاء بيقولوا إننا غاليين',
    'Analysing…' => 'بيحلّل…',
