    'Answer a voice note with a voice note (for people who cannot read)' => 'رد على الفويس بفويس (للي مش بيعرف يقرا)',
    'When someone asks for a person, tell that person on their own WhatsApp (who, number, what about)' => 'لما حد يطلب يكلم شخص، ابعت للشخص ده على واتسابه (مين، ورقمه، وبخصوص إيه)',
    'Phones that get it (empty = this number\'s own chat)' => 'الأرقام اللي توصلها الرسالة (فاضي = شات الرقم مع نفسه)',
    '# Linking by QR code' => '# الربط بكود QR',
    'Numbers are linked the way WhatsApp Web is (a QR code), not through Meta\'s official business API. Using a number stays subject to WhatsApp\'s terms and rules: bulk or unwanted messages, spam or many messages to new contacts can get the number limited or banned by WhatsApp. We are not responsible for a number stopped by WhatsApp because of such use.' => 'الأرقام بتتربط بنفس طريقة واتساب ويب (كود QR)، مش عن طريق الواجهة الرسمية من Meta. واستخدام الرقم بيفضل خاضع لشروط وقواعد واتساب: الرسايل الجماعية أو المزعجة أو السبام أو رسايل كتير لأرقام جديدة ممكن تخلّي واتساب يقيّد الرقم أو يحظره. وإحنا مش مسؤولين عن أي رقم يتوقف من واتساب بسبب استخدام زي ده.',
    'Linked by QR code like WhatsApp Web, not through Meta\'s official API: the number stays subject to WhatsApp\'s rules. Bulk or unwanted messages and spam can get it limited or banned by WhatsApp, and we are not responsible for a ban caused by misuse.' => 'الربط بكود QR زي واتساب ويب، مش عن طريق الواجهة الرسمية من Meta، فالرقم خاضع لقواعد واتساب. الرسايل الجماعية أو المزعجة والسبام ممكن تخلّي واتساب يقيّد الرقم أو يحظره، وإحنا مش مسؤولين عن الحظر بسبب سوء الاستخدام.',
