    'The old number\'s chats are kept as a separate read-only history.' => 'محادثات الرقم القديم اتحفظت لوحدها للقراية بس.',
    'Number removed. Its gateway stops within a minute; all its history stays readable under 🗄️ in the numbers list.' => 'الرقم اتشال. البوابة بتاعته هتقف خلال دقيقة، وكل تاريخه محفوظ ويتقري من 🗄️ في قايمة الأرقام.',
