    'Bot quality' => 'جودة البوت',
    'People rate a reply by a reaction (👍 ❤️ / 👎) or by the words right after it — nobody is asked. Every week real questions are asked to the bot again and scored against the team\'s answer; the report goes to the admins.' => 'الناس بتقيّم الرد بتفاعل (👍 ❤️ / 👎) أو بالكلام اللي بعده على طول — من غير ما حد يتسأل. وكل أسبوع أسئلة حقيقية بتتسأل للبوت تاني وتتقارن برد الفريق؛ والتقرير بيوصل للأدمن.',
    'Test score' => 'درجة الاختبار',
