    'Follow-up & analysis' => 'المتابعة والتحليل',
    'Each case looked at from every angle, the stage of the treatment and the progress over time. Press Analyse, or write the analysis command with the case ID in a group.' => 'كل حالة متحللة من كل جانب، ومرحلة العلاج والتقدّم مع الوقت. دوس «حلّل دلوقتي»، أو اكتب أمر التحليل ومعاه رقم الحالة في الجروب.',
    'Getting worse' => 'بتسوء',
    'Analysed' => 'اتحللت',
    'Average progress' => 'متوسط التقدّم',
    'Analyse now' => 'حلّل دلوقتي',
    'Analysis by angle is not set for this business type (Business profile → analysis_axes).' => 'التحليل بالجوانب مش متفعّل لنوع النشاط ده (ملف النشاط ← analysis_axes).',
    'Analyse a case by angle and its treatment progress: the command + ID, name or tag' => 'تحليل الحالة بالجوانب وتقدّم العلاج: الأمر + ID أو الاسم أو منشن',
    'Analysis is not set for this business type.' => 'التحليل مش متفعّل لنوع النشاط ده.',
    'Search name, number…' => 'دوّر بالاسم أو الرقم…',
    'Suggestions' => 'اقتراحات',
    'Suggest a written text, a program or a recording for this person' => 'اقترح نص مكتوب أو برنامج أو تسجيل للشخص ده',
    'Reading the chat and what the bot learned…' => 'بقرا المحادثة واللي البوت اتعلّمه…',
    'Fits this person' => 'مناسب للشخص ده',
    'Most used (2 times or more)' => 'الأكثر استخداماً (مرتين أو أكتر)',
    'Nothing fits yet — the person has not described their case.' => 'لسه مفيش حاجة مناسبة — الشخص ما وصفش حالته.',
    'matches the person\'s words' => 'مطابق لكلام الشخص',
    'the team used it for alike cases' => 'الفريق استخدمه لحالات شبهها',
    'often sent' => 'بيتبعت كتير',
    'Private chats all day and night (the hours above are for the groups that have no hours of their own)' => 'الشات الخاص طول اليوم والليل (الساعات اللي فوق للجروبات اللي ملهاش ساعات خاصة)',
    'This group\'s working hours' => 'ساعات عمل الجروب ده',
    'as the bot' => 'زي البوت',
    'working hours a day' => 'ساعة عمل في اليوم',
    'all day' => 'اليوم كله',
    'Typed by the owner in a customer\'s chat: the bot answers there again (separated by ,)' => 'يكتبها صاحب الرقم في شات العميل: البوت يرجع يرد هناك (افصل بفاصلة)',
    'Matches' => 'التطابق',
    'No suggestions — press Enter to search all messages.' => 'مفيش اقتراحات — دوس Enter للبحث في كل الرسايل.',
    'Enter = search all messages' => 'Enter = بحث في كل الرسايل',
    'choose' => 'اختيار',
    'Match' => 'التطابق',
    'After a crisis message the bot stays quiet in that chat for (hours, 0 = until /start)' => 'بعد رسالة أزمة البوت يسكت في الشات ده لمدة (ساعات، 0 = لحد /start)',
    'The bot\'s status (from a test number or the own phone, separated by ,)' => 'حالة البوت (من رقم تيست أو موبايل الرقم نفسه، افصل بفاصلة)',
    'Choose a group or the private chats…' => 'اختار جروب أو المحادثات الخاصة…',
    'Extra details asked on the join page' => 'بيانات إضافية مطلوبة في صفحة الدخول',
    'Add a field' => 'ضيف خانة',
    'e.g. Age, Country, Question' => 'مثلاً: السن، البلد، سؤالك',
    'Required' => 'مطلوب',
    'Fill in:' => 'اكتب:',
    'Boxes people fill before they enter (name is always asked). Mark a box Required so they cannot enter without it.' => 'خانات بيملاها الناس قبل ما يدخلوا (الاسم بيتطلب دايماً). علّم «مطلوب» علشان محدش يدخل من غيرها.',
    'People from a WhatsApp group or a private chat who get a private link to open the meeting — no login needed. Choose a group or the private chats, then tap the people.' => 'ناس من جروب واتساب أو محادثة خاصة بياخدوا لينك خاص يفتحوا بيه الاجتماع من غير تسجيل دخول. اختار جروب أو المحادثات الخاصة وبعدين دوس على الأشخاص.',
    'The name people see on the join page, e.g. Weekly lesson.' => 'الاسم اللي الناس بتشوفه في صفحة الدخول، مثلاً: درس الأسبوع.',
    'English letters, numbers and dashes only; it becomes the fixed link you share. Empty = made up for you.' => 'حروف إنجليزي وأرقام وشرطة بس؛ ده بيبقى اللينك الثابت اللي بتبعته. لو سبته فاضي هيتعمل لوحده.',
    'Open meet.new in Google, copy the link and paste it here — or press Create automatically. People never see it before you open the meeting.' => 'افتح meet.new من جوجل، انسخ اللينك والزقه هنا — أو دوس «إنشاء تلقائي». الناس مش بتشوفه غير لما تفتح الاجتماع.',
    'A line or two shown under the title: what the meeting is about, when, what to prepare.' => 'سطر أو اتنين تحت العنوان: الاجتماع عن إيه، إمتى، ومحتاجين يجهزوا إيه.',
    'Automatic: anyone with the link enters once a host opens the meeting. Password: they must also type the password you set.' => 'تلقائي: أي حد معاه اللينك بيدخل أول ما المضيف يفتح الاجتماع. باسورد: لازم كمان يكتب الباسورد اللي حددته.',
    'Shared with the people you invite; they type it on the join page.' => 'بتديه للناس اللي بتعزمهم، وبيكتبوه في صفحة الدخول.',
    'When this many people are inside, new ones see “the meeting is full”. 0 = no limit.' => 'لما العدد ده يكمل، اللي جاي يشوف «الاجتماع مليان». 0 = من غير حد.',
    'Each guest waits on a page until a host lets them in from “Who joined”.' => 'كل ضيف بيستنى في صفحة لحد ما مضيف يدخّله من «مين دخل».',
    'Once any host has entered, waiting guests are let in by themselves.' => 'أول ما أي مضيف يدخل، الضيوف اللي مستنيين بيدخلوا لوحدهم.',
    'If nobody closes it, the meeting closes by itself after this many hours.' => 'لو محدش قفله، الاجتماع بيتقفل لوحده بعد عدد الساعات ده.',
    'The join form also asks for a mobile number, so you know who came.' => 'صفحة الدخول بتطلب رقم الموبايل كمان، علشان تعرف مين حضر.',
    'Google Meet starts recording when the call starts; the file goes to the organiser\'s Drive.' => 'جوجل ميت بيبدأ يسجّل أول ما المكالمة تبدأ، والملف بيروح على درايف صاحب الاجتماع.',
    'Google Meet writes what was said into a document in the organiser\'s Drive.' => 'جوجل ميت بيكتب الكلام اللي اتقال في ملف على درايف صاحب الاجتماع.',
    'People of this number who may open and close the meeting from the dashboard.' => 'ناس الرقم ده اللي يقدروا يفتحوا ويقفلوا الاجتماع من اللوحة.',
    'People from a WhatsApp group who get a private link to open the meeting — no login needed. Choose a group, then tap the members.' => 'ناس من جروب واتساب بياخدوا لينك خاص يفتحوا بيه الاجتماع من غير تسجيل دخول. اختار الجروب وبعدين دوس على الأعضاء.',
    'Empty = the default text shown in grey.' => 'لو فاضي = النص الرمادي الافتراضي.',
