    '💾 Save' => '💾 حفظ',
    'Sees and manages everything: all numbers, users and system settings.' => 'بيشوف ويدير كل حاجة: كل الأرقام والمستخدمين وإعدادات النظام.',
    'Links their own number and runs everything of it.' => 'بيربط رقمه ويدير كل حاجة فيه.',
    'Extra features' => 'مميزات إضافية',
    'none' => 'مفيش',
    'Cannot add users, change their permissions or see system settings.' => 'ما يقدرش يضيف مستخدمين ولا يغيّر صلاحياته ولا يشوف إعدادات النظام.',
    'Links their own number after signing in.' => 'بيربط رقمه بعد ما يدخل.',
    'pages' => 'صفحة',
    'All pages of their numbers, except users and technical pages.' => 'كل صفحات أرقامه، ما عدا المستخدمين والصفحات الفنية.',
