    'Case settings' => 'إعدادات الحالات',
    'What a case means on this number: a patient, a support ticket or any follow-up. The words and fields below are used in the form, the list and the report.' => 'الحالة يعني إيه على الرقم ده: مريض، أو تذكرة دعم، أو أي متابعة. الكلمات والحقول دي بتظهر في النموذج والقايمة والتقرير.',
