    'See the dashboard as this user sees it' => 'شوف اللوحة زي ما المستخدم ده بيشوفها',
    'Managed by their client' => 'بيديره العميل بتاعه',
    'Wide permissions on your panel: all chats, assigning, and deleting when you allow it.' => 'صلاحيات أوسع في لوحتك: كل المحادثات، والتوزيع، والمسح لو سمحتله.',
    'Their own chats and the ones nobody took yet. Never deletes chats or messages.' => 'محادثاته هو واللي لسه محدش استلمها. عمره ما يمسح محادثة أو رسالة.',
    'Supervisors and employees of your panel. Each one signs in with their own password and a code sent to their own WhatsApp, and sees only what you allow.' => 'المسئولين والموظفين بتوع لوحتك. كل واحد بيدخل بباسورد خاص بيه وكود بيوصله على واتساب، ومش بيشوف غير اللي إنت سامحله بيه.',
    'Your plan is full. Ask the administrator for more users.' => 'باقتك اكتملت. اطلب من الإدارة تزود عدد المستخدمين.',
