    '🧹 Delete chats' => '🧹 مسح المحادثات',
    'An employee sees the chats given to them and the chats nobody has taken yet, and can never delete chats or messages.' => 'الموظف بيشوف المحادثات المحوّلة له واللي لسه محدش استلمها، وعمره ما يقدر يمسح محادثة أو رسالة.',
    '✅ Account active' => '✅ الحساب شغال',
    'Untick to stop this user signing in, without deleting them.' => 'شيل العلامة عشان توقف دخوله من غير ما تمسحه.',
