    'Give it back' => 'رجّعها',
    'Delete this chat? It is deleted from WhatsApp on this number and from the dashboard. New messages from this person will show again.' => 'تمسح المحادثة دي؟ هتتمسح من واتساب على الرقم ده ومن اللوحة. الرسايل الجديدة من الشخص ده هتظهر تاني عادي.',
    'Chat deleted' => 'المحادثة اتمسحت',
    'removed from the dashboard only' => 'اتشالت من اللوحة بس',
    'Delete this message for everyone? (WhatsApp allows it for about two days; after that it is deleted from this number only.)' => 'تمسح الرسالة دي عند الكل؟ (واتساب بيسمح بكده لحد حوالي يومين؛ بعد كده بتتمسح من الرقم ده بس.)',
    'Delete this message? It is deleted from this number and the dashboard; the other person keeps their copy.' => 'تمسح الرسالة دي؟ هتتمسح من الرقم ده ومن اللوحة؛ الطرف التاني نسخته بتفضل عنده.',
