    'You can take a free conversation or give back your own; ask your supervisor to assign it to someone else.' => 'تقدر تستلم محادثة محدش واخدها أو ترجّع محادثتك؛ لو عايز تحوّلها لحد تاني اطلب من المسئول.',
    'Only the owner or a supervisor can change the label list.' => 'صاحب اللوحة أو المسئول بس اللي يغيّر قايمة التصنيفات.',
