    'Documents (PDF, Word, Excel…)' => 'المستندات (PDF و Word و Excel…)',
    'Download automatically' => 'التحميل التلقائي',
    'up to' => 'لحد',
    'Ticked kinds are saved on the server as they arrive (and from older chats in the background). Larger files are fetched only when someone opens them. The same file is never kept twice.' => 'الأنواع المتعلّم عليها بتتحفظ على السيرفر أول ما توصل (والقديمة بتتحمل في الخلفية). الملفات الأكبر من الحد بتتحمل بس لما حد يفتحها. ونفس الملف مش بيتحفظ مرتين.',
    '🔗 Google account' => '🔗 حساب جوجل',
    'Your own Google account for your panel: importing learning files from your Google Drive and creating Google Meet links on your calendar. Only your panel uses it.' => 'حساب جوجل بتاعك للوحتك: استيراد ملفات التعلّم من جوجل درايف بتاعك، وعمل لينكات Google Meet على التقويم بتاعك. لوحتك بس هي اللي بتستخدمه.',
    'Not connected yet.' => 'لسه مش متصل.',
    'Connect my Google account' => 'اربط حساب جوجل بتاعي',
    'Disconnect your Google account?' => 'تفصل حساب جوجل بتاعك؟',
    'Some permissions were not given:' => 'فيه صلاحيات ما اتدتش:',
    'Google sign-in is not set up on this installation yet. Ask the administrator.' => 'تسجيل الدخول بجوجل لسه مش متجهز على النظام. اطلب من الإدارة.',
    'Connect your Google account first (My account → Google account).' => 'اربط حساب جوجل بتاعك الأول (حسابي ← حساب جوجل).',
    'Only the panel owner connects its Google account.' => 'صاحب اللوحة بس هو اللي يربط حساب جوجل.',
    'Google connected.' => 'جوجل اتربط.',
    '💾 Backup to my Google Drive' => '💾 نسخة احتياطية على جوجل درايف بتاعي',
    'All chats and data of your numbers (cases, notes, bot, learning, team) in one file in your own Google Drive. Connect your Google account above first.' => 'كل محادثات وبيانات أرقامك (الحالات والملاحظات والبوت والتعلّم والفريق) في ملف واحد على جوجل درايف بتاعك. اربط حساب جوجل اللي فوق الأول.',
    'Every day at' => 'كل يوم الساعة',
    'Include photos and recordings' => 'ضم الصور والصوتيات',
    'Keep the last' => 'احتفظ بآخر',
    '⬆️ Back up now' => '⬆️ انسخ دلوقتي',
    'Running…' => 'شغالة…',
    'copies on Drive' => 'نسخة على درايف',
    'The backup started in the background. It takes a few minutes.' => 'النسخة بدأت في الخلفية، وهتاخد كام دقيقة.',
    'Backup is not part of your plan.' => 'النسخ الاحتياطي مش ضمن باقتك.',
    'No WhatsApp number is linked yet.' => 'لسه مفيش رقم واتساب مربوط.',
    'Add to a group' => 'إضافة لجروب',
    'This number is not an admin of any group. Only a group admin can add people.' => 'الرقم ده مش أدمن في أي جروب. الأدمن بس هو اللي يقدر يضيف.',
    'Groups where this number is an admin' => 'الجروبات اللي الرقم ده أدمن فيها',
    'left today' => 'المتبقي النهارده',
    'Send invite link' => 'ابعت لينك الدعوة',
    'Send the group invite link to this person in the chat?' => 'تبعت لينك دعوة الجروب للشخص ده في الشات؟',
    'Invite link sent' => 'لينك الدعوة اتبعت',
    'Added to the group' => 'اتضاف للجروب',
    'Already in this group' => 'موجود في الجروب ده بالفعل',
    'Their privacy settings do not allow adding them. Send them the invite link instead.' => 'إعدادات الخصوصية عنده مش بتسمح بإضافته. ابعتله لينك الدعوة بدل كده.',
    'They left this group recently; WhatsApp does not allow adding them again yet. Send the invite link.' => 'خرج من الجروب ده قريب، وواتساب مش بيسمح بإضافته تاني دلوقتي. ابعتله لينك الدعوة.',
    'WhatsApp refused (they blocked this number).' => 'واتساب رفض (عامل بلوك للرقم ده).',
    '👥 Add people to groups' => '👥 إضافة أشخاص للجروبات',
    'This number is not an admin of that group.' => 'الرقم ده مش أدمن في الجروب ده.',
    'Today\'s limit of people added to groups is reached (it protects the number). Send an invite link instead, or try tomorrow.' => 'وصلت لحد الإضافة للجروبات النهارده (عشان نحمي الرقم). ابعت لينك دعوة بدل كده، أو جرّب بكره.',
    'People added to groups from chats, per number per day (protects the number)' => 'عدد الأشخاص اللي بيتضافوا لجروبات من الشات في اليوم لكل رقم (لحماية الرقم)',
    'Their privacy settings do not allow adding them directly, so WhatsApp\'s personal group invitation was sent to them in the chat. They join with one tap (it works even if they were removed before).' => 'إعدادات الخصوصية عنده مش بتسمح بإضافته مباشرة، فاتبعتله دعوة الجروب الخاصة بتاعة واتساب في الشات. بينضم بضغطة واحدة (حتى لو كان اتشال من الجروب قبل كده).',
    'This person was removed from this group earlier, so WhatsApp refuses the public link. The add / personal invitation is used instead.' => 'الشخص ده اتشال من الجروب ده قبل كده، فواتساب بيرفض اللينك العام. هنستخدم الإضافة المباشرة أو الدعوة الخاصة بدل كده.',
    'Personal invitation sent' => 'الدعوة الخاصة اتبعتت',
    'Joining groups' => 'الانضمام للجروبات',
    'When someone asks to join or rejoin a group, the bot adds them (or sends WhatsApp\'s personal invitation)' => 'لما حد يطلب يدخل أو يرجع جروب، البوت يضيفه (أو يبعتله دعوة واتساب الخاصة)',
    'The bot adds people who ask to join (automatic mode only)' => 'البوت يضيف اللي بيطلب ينضم (في الوضع التلقائي بس)',
    'Groups the bot may add people to' => 'الجروبات اللي البوت مسموحله يضيف فيها',
    'Someone an admin removed from the group asks to come back' => 'حد الأدمن شاله من الجروب وعايز يرجع',
    'Add them back (or send the personal invitation)' => 'رجّعه (أو ابعتله الدعوة الخاصة)',
    'Leave it to the team' => 'سيبها للفريق',
    'People who left by themselves are added like anyone else. The public link is never sent to someone who was removed, because WhatsApp refuses it. Replies: Settings → Message templates (Bot: …).' => 'اللي خرج بنفسه بيتضاف عادي زي أي حد. اللي اتشال مبيتبعتلوش اللينك العام أبداً لأن واتساب بيرفضه. نصوص الردود: الإعدادات ← قوالب الرسائل (Bot: …).',
    'This number is not an admin of any group.' => 'الرقم ده مش أدمن في أي جروب.',
    'Only a group admin can add people. Make this number an admin of a group, then come back.' => 'الأدمن بس هو اللي يقدر يضيف أشخاص. خلّي الرقم ده أدمن في جروب وارجع تاني.',
    'Let the bot add people to groups' => 'خلّي البوت يضيف الناس للجروبات',
    'When someone asks to join or rejoin a group, or says the link does not work, the bot adds them and tells them what happened.' => 'لما حد يطلب يدخل أو يرجع جروب، أو يقول إن اللينك مش شغال، البوت بيضيفه ويقوله حصل إيه.',
